<template>
  <div class="research-page">
    <WorkbenchNavigation />
    <main id="workspace-content" tabindex="-1" class="research-layout">
      <aside class="project-index">
        <h1>{{ $t('research.title') }}</h1><p class="muted">{{ $t('research.intro') }}</p>
        <form class="search-row" @submit.prevent="loadProjects(false)"><label class="sr-only" for="research-search">{{ $t('research.search') }}</label><input id="research-search" v-model="query" type="search" :placeholder="$t('research.search')" /><button :disabled="listBusy">{{ $t('research.searchButton') }}</button></form>
        <label class="checkbox"><input v-model="archived" type="checkbox" @change="loadProjects(false)" />{{ $t('research.showArchived') }}</label>
        <p v-if="listError" role="alert" class="error">{{ listError }} <button @click="loadProjects(false)">{{ $t('research.retry') }}</button></p>
        <p v-if="listBusy" role="status">{{ $t('research.loading') }}</p>
