        <ul class="project-list"><li v-for="item in projects" :key="item.project_id"><RouterLink :to="`/workbench/${item.project_id}`" :aria-current="item.project_id === projectId ? 'page' : undefined"><strong>{{ item.name || item.project_id }}</strong><small>{{ statusLabel(item.status) }} <span v-if="item.demo">· {{ $t('research.synthetic') }}</span></small></RouterLink></li></ul>
        <button v-if="hasMoreProjects" :disabled="listBusy" @click="loadProjects(true)">{{ $t('research.loadMore') }}</button>
        <details class="new-research"><summary>{{ $t('research.newProject') }}</summary><form @submit.prevent="createProject"><label for="research-name">{{ $t('research.name') }}</label><input id="research-name" v-model="draft.name" maxlength="200" required /><label for="research-question">{{ $t('research.question') }}</label><textarea id="research-question" v-model="draft.requirement" rows="3" /><p class="muted">{{ $t('research.localOnly') }}</p><button class="primary" :disabled="busy || !draft.name.trim()">{{ $t('research.createDraft') }}</button></form></details>
      </aside>
      <section class="research-content">
        <p v-if="error" class="error" role="alert">{{ error }} <button :disabled="loading" @click="refreshCurrent">{{ $t('research.retry') }}</button></p><p v-if="notice" role="status" class="notice">{{ notice }}</p>
        <p v-if="loading" role="status">{{ $t('research.loading') }}</p>
        <template v-if="mainSection === 'tasks'">
          <div class="heading-row"><h2>{{ $t('research.tasks') }}</h2><button @click="loadOverview" :disabled="loading">{{ $t('research.refresh') }}</button></div><p class="muted">{{ $t('research.readOnlyTasks') }}</p>
          <p v-if="!tasks.length && !taskRuns.length" class="empty">{{ $t('research.noTasks') }}</p>
          <article v-for="task in tasks" :key="task.task_id" class="record"><div class="heading-row"><h3>{{ task.description || task.task_type || task.task_id }}</h3><span class="tag">{{ statusLabel(task.status) }}</span></div><p v-if="task.message">{{ task.message }}</p><p v-if="task.error" class="error">{{ task.error }}</p><progress v-if="hasVerifiedProgress(task)" :value="task.progress" max="100" :aria-label="$t('research.progress')" /><TaskRecordMeta :record="task" /></article>
          <article v-for="run in taskRuns" :key="run.run_id" class="record"><h3>{{ run.simulation_id }}</h3><p>{{ statusLabel(run.status) }}</p><p v-if="run.message || run.detail?.message">{{ run.message || run.detail?.message }}</p><p v-if="run.error || run.detail?.error" class="error">{{ run.error || run.detail?.error }}</p><TaskRecordMeta :record="run" /><RouterLink :to="`/simulation/${run.simulation_id}/start`">{{ $t('research.openRun') }}</RouterLink></article>
        </template>
        <template v-else-if="mainSection === 'demos'">
          <h2>{{ $t('research.demos') }}</h2><p class="muted">{{ $t('research.demoHelp') }}</p><article v-for="demo in demos" :key="demo.id" class="record"><span class="tag">{{ $t('research.synthetic') }}</span><h3>{{ demo.title }}</h3><p>{{ demo.description }}</p><button :disabled="busy" @click="openDemo(demo.id)">{{ $t('research.openDemo') }}</button></article>
        </template>
        <template v-else-if="detail">
          <header class="project-heading"><div><p v-if="detail.project.demo" class="tag">{{ $t('research.synthetic') }}</p><h2>{{ detail.project.name }}</h2><p class="requirement">{{ detail.project.simulation_requirement }}</p><span class="muted">{{ statusLabel(detail.project.status) }}</span></div><button :disabled="loading" @click="loadDetail">{{ $t('research.refresh') }}</button></header>
          <details class="project-controls"><summary>{{ $t('research.manage') }}</summary><form class="inline-form" @submit.prevent="renameProject"><label for="rename-project">{{ $t('research.name') }}</label><input id="rename-project" v-model="rename" maxlength="200" required /><button :disabled="busy || !rename.trim()">{{ $t('research.rename') }}</button></form><div class="button-row"><button :disabled="busy" @click="archiveProject">{{ $t(detail.project.archived ? 'research.restore' : 'research.archive') }}</button><button :disabled="busy" @click="copyProject">{{ $t('research.clone') }}</button><a class="button" :href="api.researchExportUrl(projectId)" target="_blank" rel="noopener noreferrer">{{ $t('research.printPreview') }}</a><button v-for="format in ['html','md','json']" :key="format" :disabled="busy" @click="exportProject(format)">{{ $t('research.export') }} {{ format.toUpperCase() }}</button></div><p class="muted">{{ $t('research.cloneHelp') }}</p></details>
          <nav class="content-tabs" :aria-label="$t('research.sections')"><button v-for="item in sections" :key="item" :aria-current="section === item ? 'page' : undefined" @click="selectSection(item)">{{ $t(`research.${item}`) }}<small v-if="item === 'sources'"> {{ sourceTotal }}</small><small v-if="item === 'references'"> {{ referenceTotal }}</small></button></nav>
          <section v-if="section === 'sources'">
            <div class="heading-row"><h3>{{ $t('research.sources') }}</h3><RouterLink class="button" :to="`/process/${projectId}`">{{ $t(detail.project.status === 'created' ? 'research.analyzeSources' : 'research.openWorkflow') }}</RouterLink></div><p class="muted">{{ $t('research.sourceHelp') }}</p>
            <p v-if="!sources.length" class="empty">{{ $t('research.noSources') }}</p><article v-for="source in sources" :key="source.source_id" class="record"><div class="heading-row"><h3>{{ source.title }}</h3><span class="tag">{{ source.source_type }}</span></div><p class="muted break">{{ source.locator || source.identity }}</p><button @click="inspectSource(source)">{{ $t('research.inspect') }}</button></article><button v-if="sources.length < sourceTotal" :disabled="pageBusy" @click="loadMore('sources')">{{ $t('research.loadMore') }}</button>
            <details class="add-source"><summary>{{ $t('research.addSource') }}</summary><form @submit.prevent="addSource"><label for="source-title">{{ $t('research.sourceTitle') }}</label><input id="source-title" v-model="sourceDraft.title" maxlength="500" required /><label for="source-identity">{{ $t('research.sourceIdentity') }}</label><input id="source-identity" v-model="sourceDraft.identity" maxlength="2000" /><label for="source-text">{{ $t('research.sourceText') }}</label><textarea id="source-text" v-model="sourceDraft.content" rows="8" required /><p class="muted">{{ $t('research.localOnly') }}</p><button class="primary" :disabled="busy || !sourceDraft.title.trim() || !sourceDraft.content.trim()">{{ $t('research.saveSource') }}</button></form></details>
            <details class="web-source"><summary>{{ $t('research.addWebSource') }}</summary><form @submit.prevent="planWeb"><label for="research-urls">{{ $t('research.webUrls') }}</label><textarea id="research-urls" v-model="urlText" rows="3" :disabled="busy" /><p class="muted">{{ $t('research.webPlanHelp') }}</p><button :disabled="busy || !urlText.trim()">{{ $t('research.previewWebPlan') }}</button></form><template v-if="webPlan"><p>{{ $t('research.webPlanSummary', {cached:webPlan.cached_pages,attempts:webPlan.new_pages}) }}</p><ul><li v-for="entry in webPlan.entries" :key="entry.url" class="break">{{ entry.url }} · {{ $t(entry.cached ? 'research.cached' : 'research.newFetch') }}</li></ul><p class="muted">{{ $t('research.updateCost') }}</p><button :disabled="busy" @click="fetchWeb">{{ $t('research.fetchPlanned') }}</button></template><div v-if="webPreview" class="web-candidates"><p role="status">{{ $t('research.webPreviewSummary',{count:webPreview.candidates?.length || 0,attempts:webPreview.collection?.attempted ?? '—',status:webPreview.collection?.status || '—'}) }}</p><p class="muted">{{ $t('research.previewNotAdopted') }}</p><article v-for="candidate in webPreview.candidates || []" :key="candidate.id || candidate.url" class="record"><label class="checkbox"><input v-model="adoptUrls" type="checkbox" :value="candidate.url" :disabled="busy || webPreview.collection?.status !== 'completed'" />{{ candidate.title }}</label><p class="break">{{ candidate.source_url || candidate.url }}</p><p class="muted">{{ $t('research.fetchedAt') }}: {{ candidate.fetched_at || $t('research.notRecorded') }} · {{ $t('research.publishedAt') }}: {{ candidate.published_at || $t('research.notRecorded') }}</p><details><summary>{{ $t('research.preservedText') }}</summary><pre>{{ candidate.markdown }}</pre></details></article><p v-if="webPreview.collection?.status !== 'completed'" class="error">{{ $t('research.previewIncomplete') }}</p><button :disabled="busy || !canAdoptWeb" @click="adoptWeb">{{ $t('research.adoptSelected',{count:adoptUrls.length}) }}</button></div><p v-if="webResult" role="status">{{ $t('research.webAdoptSummary',{count:webResult.records?.length || 0}) }}</p></details>
            <details><summary>{{ $t('research.legacySources') }}</summary><p class="muted">{{ $t('research.legacyHelp') }}</p><button :disabled="busy" @click="importLegacy">{{ $t('research.indexLegacy') }}</button></details>
          </section>
          <section v-else-if="section === 'references'">
            <h3>{{ $t('research.references') }}</h3><p class="muted">{{ $t('research.semanticNotEvaluated') }}</p><p v-if="!references.length" class="empty">{{ $t('research.noReferences') }}</p><article v-for="item in references" :key="item.reference_id" class="record"><div class="button-row"><span class="tag">{{ $t(`research.categories.${item.category}`) }}</span><span class="tag">{{ $t(`research.relations.${item.relation}`) }}</span></div><p class="preserved">{{ item.note }}</p><small>{{ item.subject_type }} · {{ item.subject_id }}</small><p>{{ $t('research.locationCheck') }}: {{ $t(`research.locations.${item.validation?.location_status || 'unverified'}`) }}</p><EventReferenceLink :project-id="projectId" :reference="item" /><button v-if="item.source_id" @click="inspectReference(item)">{{ $t('research.inspect') }}</button></article><button v-if="references.length < referenceTotal" :disabled="pageBusy" @click="loadMore('references')">{{ $t('research.loadMore') }}</button>
            <details><summary>{{ $t('research.addNote') }}</summary><form @submit.prevent="addNote"><label for="note-category">{{ $t('research.category') }}</label><select id="note-category" v-model="noteDraft.category"><option value="user_assumption">{{ $t('research.categories.user_assumption') }}</option><option value="model_inference">{{ $t('research.categories.model_inference') }}</option></select><label for="note-relation">{{ $t('research.relation') }}</label><select id="note-relation" v-model="noteDraft.relation"><option v-for="value in ['supports','contradicts','insufficient']" :key="value" :value="value">{{ $t(`research.relations.${value}`) }}</option></select><label for="note-content">{{ $t('research.note') }}</label><textarea id="note-content" v-model="noteDraft.note" rows="4" required /><button :disabled="busy || !noteDraft.note.trim()">{{ $t('research.saveNote') }}</button></form></details>
          </section>
          <section v-else-if="section === 'runs'">
            <RunReplay :runs="detail.runs" :project-id="projectId" @saved="refreshEvidence" @inspect="inspectReference" /><h3>{{ $t('research.runs') }}</h3><p v-if="!detail.runs.length" class="empty">{{ $t('research.noRuns') }}</p><article v-for="run in detail.runs" :key="run.run_id || run.simulation_id" class="record"><div class="heading-row"><h3 class="break">{{ run.simulation_id }}</h3><span class="tag">{{ statusLabel(run.status) }}</span></div><p v-if="run.status !== 'completed'" class="muted">{{ $t('research.incompleteRun') }}</p><p v-if="run.graph_ready !== true" class="muted">{{ $t('research.graphNotReady') }}</p><RouterLink :to="`/simulation/${run.simulation_id}/start`">{{ $t('research.openRun') }}</RouterLink><details><summary>{{ $t('research.settingsSnapshot') }}</summary><pre>{{ JSON.stringify(run.manifest || {}, null, 2) }}</pre></details></article>
          </section>
          <section v-else-if="section === 'reports'">
            <h3>{{ $t('research.reports') }}</h3><p v-if="!detail.reports.length" class="empty">{{ $t('research.noReports') }}</p><article v-for="report in detail.reports" :key="report.report_id" class="record saved-report"><div class="heading-row"><h3>{{ report.outline?.title || report.report_id }}</h3><span class="tag">{{ statusLabel(report.status) }}</span></div><p v-if="report.status !== 'completed'" class="error">{{ $t('research.incompleteReport') }}</p><p v-if="report.manifest?.kind === 'synthetic_fixture'" class="muted">{{ $t('research.demoHelp') }}</p><p class="preserved">{{ report.markdown_content || report.outline?.summary }}</p><EvidenceLinks :project-id="projectId" subject-type="report" :subject-id="report.report_id" /><section v-for="(part,index) in (report.outline?.sections || [])" :key="index"><h4>{{ part.title }}</h4><p v-if="!report.markdown_content" class="preserved">{{ part.content || $t('research.sectionMissing') }}</p><EvidenceLinks :project-id="projectId" subject-type="report_section" :subject-id="`${report.report_id}:section:${index + 1}`" /></section><ReportVersionAction v-if="report.simulation_id" :simulation-id="report.simulation_id" :eligible="detail.runs.some(run=>run.simulation_id===report.simulation_id && run.status==='completed' && run.graph_ready===true && run.run_id && !run.legacy)" @created="loadDetail" /><RouterLink :to="`/report/${report.report_id}`">{{ $t('research.openReport') }}</RouterLink></article>
          </section>
          <section v-else-if="section === 'plans'"><h3>{{ $t('research.plans') }}</h3><p class="notice">{{ $t('research.planDisabledHelp') }}</p><p v-if="planError" class="error" role="alert">{{ planError }} <button @click="loadPlans">{{ $t('research.retry') }}</button></p><article v-for="plan in plans" :key="plan.plan_id" class="record"><span class="tag">{{ $t('research.disabled') }}</span><h4>{{ $t(`research.planKinds.${plan.kind}`) }}</h4><dl><dt>{{ $t('research.frequency') }}</dt><dd>{{ plan.definition.frequency }}</dd><dt>{{ $t('research.timezone') }}</dt><dd>{{ plan.definition.timezone }}</dd><dt>{{ $t('research.planScope') }}</dt><dd>{{ plan.definition.scope }}</dd><dt>{{ $t('research.planBudget') }}</dt><dd>{{ plan.definition.budget?.max_attempts ?? '—' }}</dd><template v-if="plan.kind === 'sensitivity'"><dt>{{ $t('research.repeatCount') }}</dt><dd>{{ plan.definition.repeat_count }}</dd><dt>{{ $t('research.planModels') }}</dt><dd>{{ (plan.definition.model_snapshots || []).map(model=>model.name || model.id).join(', ') || (plan.definition.model_profile_ids || []).join(', ') }}</dd><dt>{{ $t('research.modelCallBudget') }}</dt><dd>{{ plan.definition.budget?.max_model_calls ?? 0 }}</dd></template></dl><p class="muted">{{ $t('research.noNextRun') }}</p></article><form class="plan-form" @submit.prevent="saveDisabledPlan"><label for="plan-kind">{{ $t('research.planKind') }}</label><select id="plan-kind" v-model="planDraft.kind"><option value="source_update">{{ $t('research.planKinds.source_update') }}</option><option value="sensitivity">{{ $t('research.planKinds.sensitivity') }}</option></select><label for="plan-frequency">{{ $t('research.frequency') }}</label><select id="plan-frequency" v-model="planDraft.frequency"><option value="daily">{{ $t('research.daily') }}</option><option value="weekly">{{ $t('research.weekly') }}</option><option value="manual">{{ $t('research.manual') }}</option></select><label for="plan-timezone">{{ $t('research.timezone') }}</label><input id="plan-timezone" v-model="planDraft.timezone" required /><label for="plan-scope">{{ $t('research.planScope') }}</label><textarea id="plan-scope" v-model="planDraft.scope" rows="3" maxlength="2000" required /><template v-if="planDraft.kind === 'source_update'"><label for="plan-budget">{{ $t('research.planBudget') }}</label><input id="plan-budget" v-model.number="planDraft.budget" type="number" min="0" max="3" step="1" required /></template><template v-else><label for="plan-repeats">{{ $t('research.repeatCount') }}</label><input id="plan-repeats" v-model.number="planDraft.repeatCount" type="number" min="1" max="5" step="1" required /><fieldset class="plan-models"><legend>{{ $t('research.planModels') }}</legend><p v-if="profilesBusy" role="status">{{ $t('research.loading') }}</p><p v-if="profilesError" class="error" role="alert">{{ profilesError }}</p><p v-if="!profilesBusy && !modelProfiles.length">{{ $t('research.noNamedModels') }} <RouterLink to="/settings">{{ $t('settings.title') }}</RouterLink></p><label v-for="profile in modelProfiles" :key="profile.id" class="checkbox"><input v-model="planDraft.modelIds" :value="profile.id" type="checkbox" :disabled="!planDraft.modelIds.includes(profile.id) && planDraft.modelIds.length >= 4" />{{ profile.name }} · {{ profile.model }}</label><button type="button" :disabled="profilesBusy" @click="loadModelProfiles">{{ $t('research.refresh') }}</button></fieldset><p>{{ $t('research.zeroModelBudget') }}</p></template><button :disabled="busy || !planDraft.scope.trim()">{{ $t('research.saveDisabledPlan') }}</button></form></section>
          <section v-else-if="section === 'quality'">
            <h3>{{ $t('research.quality') }}</h3><p class="muted">{{ $t('research.qualityHelp') }}</p><p v-if="qualityError" class="error" role="alert">{{ qualityError }} <button @click="loadQuality()">{{ $t('research.retry') }}</button></p><template v-if="quality"><div class="quality-grid"><article v-for="metric in ['source_preservation','citation_location']" :key="metric" class="record"><h4>{{ $t(`research.metrics.${metric}`) }}</h4><p class="metric">{{ quality[metric]?.value == null ? $t('research.noData') : `${quality[metric].numerator} / ${quality[metric].denominator}` }}</p><p class="muted">{{ quality[metric]?.definition }}</p></article></div><p>{{ $t('research.runCounts', quality.run_counts || {total:0,completed:0,incomplete:0}) }}</p><ObservedQuality :title="$t('research.repeatTitle')" :metric="quality.repeat_stability" /><ObservedQuality :title="$t('research.sensitivityTitle')" :metric="quality.model_sensitivity" /><p>{{ $t('research.realValidation') }}</p><h4>{{ $t('research.assumptions') }} ({{ quality.assumptions?.length || 0 }})</h4><p v-for="item in quality.assumptions" :key="item.reference_id" class="preserved">{{ item.note }}</p><h4>{{ $t('research.contradictions') }} ({{ quality.contradictions?.length || 0 }})</h4><p v-for="item in quality.contradictions" :key="item.reference_id" class="preserved">{{ item.note }}</p><h4>{{ $t('research.limitations') }}</h4><ul><li v-for="item in quality.limitations" :key="item">{{ item }}</li></ul></template>
          </section>
        </template>
        <div v-else-if="!loading && !projectId" class="welcome"><p class="eyebrow">MIROFISH</p><h2>{{ $t('research.welcome') }}</h2><p>{{ $t('research.welcomeHelp') }}</p><RouterLink class="button primary" to="/workbench?view=demos">{{ $t('research.tryDemo') }}</RouterLink></div>
      </section>
    </main>
    <EvidenceInspector v-if="inspector" v-bind="inspector" :project-id="projectId" @close="inspector = null" @saved="refreshEvidence" />
  </div>
</template>

<script setup>
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useI18n } from 'vue-i18n'
import WorkbenchNavigation from '../components/WorkbenchNavigation.vue'
import EvidenceInspector from '../components/EvidenceInspector.vue'
import RunReplay from '../components/RunReplay.vue'
import EventReferenceLink from '../components/EventReferenceLink.vue'
import EvidenceLinks from '../components/EvidenceLinks.vue'
import ObservedQuality from '../components/ObservedQuality.vue'
import ReportVersionAction from '../components/ReportVersionAction.vue'
import TaskRecordMeta from '../components/TaskRecordMeta.vue'
import * as api from '../api/workbench'
const props = defineProps({ projectId: String })
const route = useRoute(), router = useRouter(), { t, te } = useI18n()
const overview = ref(route.query.view)
watch(() => route.query.view, value => { if (route.name === 'Workbench') overview.value = value })
const mainSection = computed(() => ['tasks','demos'].includes(overview.value) && !props.projectId ? overview.value : 'projects')
const sections = ['sources','references','runs','reports','quality','plans'], section = ref(sections.includes(route.query.section) ? route.query.section : 'sources')
watch(()=>route.query.section,value=>{if(route.name==='Workbench'&&sections.includes(value))section.value=value})
function selectSection(value){section.value=value;router.replace({query:{...route.query,section:value}})}
const query = ref(''), archived = ref(false), projects = ref([]), hasMoreProjects = ref(false), listBusy = ref(false), listError = ref('')
const detail = ref(null), sources = ref([]), references = ref([]), sourceTotal = ref(0), referenceTotal = ref(0), quality = ref(null), qualityError = ref(''), rename = ref('')
const loading = ref(false), busy = ref(false), pageBusy = ref(false), error = ref(''), notice = ref(''), inspector = ref(null), tasks = ref([]), taskRuns = ref([]), demos = ref([])
const draft = reactive({name:'',requirement:''}), sourceDraft = reactive({title:'',content:'',identity:''}), noteDraft = reactive({category:'user_assumption',relation:'insufficient',note:''})
const urlText=ref(''),webPlan=ref(null),webResult=ref(null),webPreview=ref(null),adoptUrls=ref([])
const canAdoptWeb=computed(()=>webPreview.value?.collection?.status==='completed'&&webPreview.value?.plan_id===webPlan.value?.plan_id&&adoptUrls.value.length>0)
const plans=ref([]),planError=ref(''),planDraft=reactive({kind:'source_update',frequency:'manual',timezone:Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC',scope:'',budget:0,repeatCount:1,modelIds:[]})
const modelProfiles=ref([]),profilesError=ref(''),profilesBusy=ref(false)
watch(()=>planDraft.kind,value=>{if(value==='sensitivity')loadModelProfiles()})
watch(section,value=>{if(value==='plans')loadPlans()})
watch(urlText,()=>{webPlan.value=null;webResult.value=null;webPreview.value=null;adoptUrls.value=[]})
let alive = true, generation = 0, listGeneration = 0, overviewRequest = 0, overviewBusy = false, taskTimer = null, overviewPending = false
function hasVerifiedProgress(task){return Number.isFinite(task.progress) && task.progress > 0 && task.progress <= 100 && (task.status==='completed' || Object.keys(task.progress_detail || {}).length > 0)}
function taskPollingAllowed(){return alive && mainSection.value==='tasks' && route.name==='Workbench' && !props.projectId && document.visibilityState!=='hidden'}
function stopTaskPolling(){if(taskTimer!==null)clearTimeout(taskTimer);taskTimer=null;overviewRequest++;overviewPending=false}
function updateTaskPolling(){if(mainSection.value!=='tasks')return;stopTaskPolling();if(taskPollingAllowed())loadOverview();else loading.value=false}
watch(()=>route.name,()=>{if(mainSection.value==='tasks')updateTaskPolling()})
const valid = token => alive && generation === token
function statusLabel(status) { return te(`research.statuses.${status}`) ? t(`research.statuses.${status}`) : (status || t('research.notRecorded')) }
async function loadProjects(more = false) {
  if (more && listBusy.value) return
  const token = ++listGeneration; listBusy.value = true; listError.value = ''
  try { const page = await api.listProjects({q:query.value,archived:archived.value ? 1 : 0,offset:more ? projects.value.length : 0,limit:50}); if (!alive || token !== listGeneration) return; projects.value = more ? [...projects.value,...page.items] : page.items; hasMoreProjects.value = page.has_more }
  catch (err) { if (alive && token === listGeneration) listError.value = err.message }
  finally { if (alive && token === listGeneration) listBusy.value = false }
}
async function loadDetail() {
  if (!props.projectId) return
  const token = ++generation; loading.value = true; error.value = ''; quality.value = null
  try { const data = await api.getResearch(props.projectId); if (!valid(token)) return; detail.value = data; rename.value = data.project.name; sources.value = data.sources.items; sourceTotal.value = data.sources.total; references.value = data.references.items; referenceTotal.value = data.references.total; await loadQuality(token); if(valid(token)&&section.value==='plans')await loadPlans() }
  catch (err) { if (valid(token)) error.value = err.message }
  finally { if (valid(token)) loading.value = false }
}
async function loadQuality(token = generation) { qualityError.value = ''; try { const data = await api.getQuality(props.projectId); if (valid(token)) quality.value = data } catch(err) { if (valid(token)) qualityError.value = err.message } }
async function loadOverview() {
  if(overviewBusy){overviewPending=true;return}
  overviewPending=false
  const token=generation,request=++overviewRequest
  overviewBusy=true;loading.value=true;error.value=''
  try {
    if (mainSection.value === 'tasks') { const data=await api.listTasks();if(valid(token)&&request===overviewRequest){tasks.value=data.items;taskRuns.value=data.runs || []} }
    else if(mainSection.value === 'demos'){const data=await api.listDemos();if(valid(token)&&request===overviewRequest)demos.value=data.items}
  }catch(err){if(valid(token)&&request===overviewRequest)error.value=err.message}
  finally{overviewBusy=false;if(valid(token)&&request===overviewRequest)loading.value=false;if(alive&&overviewPending&&route.name==='Workbench'&&!props.projectId){overviewPending=false;if(mainSection.value!=='tasks'||taskPollingAllowed())loadOverview()}else if(taskPollingAllowed()){if(taskTimer!==null)clearTimeout(taskTimer);taskTimer=setTimeout(()=>{taskTimer=null;loadOverview()},5000)}}
}
function refreshCurrent() { return props.projectId ? loadDetail() : loadOverview() }
async function mutate(action) { if (busy.value) return; const token = generation; busy.value = true; error.value = ''; notice.value = ''; try { await action(() => valid(token)) } catch(err) { if (valid(token)) error.value = err.message } finally { if (alive) busy.value = false } }
const createProject = () => mutate(async current => { const result = await api.createResearch({...draft}); if (!current()) return; draft.name = draft.requirement = ''; await router.push(`/workbench/${result.project_id}`); await loadProjects() })
const renameProject = () => mutate(async current => { await api.editResearch(props.projectId,{name:rename.value}); if (!current()) return; detail.value.project.name = rename.value; notice.value = t('research.saved'); await loadProjects() })
const archiveProject = () => mutate(async current => { const value = !detail.value.project.archived; await api.editResearch(props.projectId,{archived:value}); if (!current()) return; detail.value.project.archived = value; notice.value = t('research.saved'); await loadProjects() })
const copyProject = () => mutate(async current => { const result = await api.cloneResearch(props.projectId); if (current()) { await router.push(`/workbench/${result.project_id}`); await loadProjects() } })
const openDemo = id => mutate(async current => { const result = await api.installDemo(id); if (current()) { await router.push(`/workbench/${result.project_id}`); await loadProjects() } })
const addSource = () => mutate(async current => { await api.saveSource(props.projectId,{title:sourceDraft.title,content:sourceDraft.content,source_type:'document',...(sourceDraft.identity.trim() ? {identity:sourceDraft.identity.trim()} : {})}); if (!current()) return; sourceDraft.title = sourceDraft.content = sourceDraft.identity = ''; await refreshEvidence(); notice.value = t('research.saved') })
const planWeb = () => mutate(async current => { const result=await api.planWebSources(props.projectId,urlText.value.split(/\r?\n/).map(value=>value.trim()).filter(Boolean));if(current()){webPlan.value=result;webResult.value=null;webPreview.value=null;adoptUrls.value=[]} })
const fetchWeb = () => mutate(async current => { if(!webPlan.value)return;webPreview.value=null;adoptUrls.value=[];const result=await api.previewWebSources(props.projectId,webPlan.value.plan_id);if(current()){webPreview.value=result;adoptUrls.value=(result.candidates || []).map(item=>item.url)} })
const adoptWeb=()=>mutate(async current=>{if(!canAdoptWeb.value)return;const result=await api.adoptWebSources(props.projectId,webPlan.value.plan_id,[...adoptUrls.value]);if(current()){webResult.value=result;await refreshEvidence();notice.value=t('research.saved')}})
async function loadPlans(){const token=generation;planError.value='';try{const result=await api.getPlans(props.projectId);if(valid(token))plans.value=result.items}catch(err){if(valid(token))planError.value=err.message}}
async function loadModelProfiles(){if(profilesBusy.value)return;const token=generation;profilesBusy.value=true;profilesError.value='';try{const result=await api.getSavedModelProfiles();if(valid(token))modelProfiles.value=result.profiles || []}catch(err){if(valid(token))profilesError.value=err.message}finally{if(alive)profilesBusy.value=false}}
const saveDisabledPlan=()=>mutate(async current=>{
  if(!Number.isInteger(planDraft.budget)||planDraft.budget<0||planDraft.budget>3||!Number.isInteger(planDraft.repeatCount)||planDraft.repeatCount<1||planDraft.repeatCount>5)throw new Error(t('research.invalidPlanBounds'))
  try{new Intl.DateTimeFormat('en',{timeZone:planDraft.timezone})}catch{throw new Error(t('research.invalidPlanTimezone'))}
  if(planDraft.kind==='sensitivity'&&(!planDraft.modelIds.length||planDraft.modelIds.some(id=>!modelProfiles.value.some(profile=>profile.id===id))))throw new Error(t('research.choosePlanModels'))
  const definition={enabled:false,frequency:planDraft.frequency,timezone:planDraft.timezone,scope:planDraft.scope,budget:{max_attempts:planDraft.kind==='source_update'?planDraft.budget:0,max_model_calls:0},...(planDraft.kind==='sensitivity'?{repeat_count:planDraft.repeatCount,model_profile_ids:[...planDraft.modelIds]}:{})}
  const result=await api.savePlan(props.projectId,{kind:planDraft.kind,definition})
  if(current()){plans.value=result.items;notice.value=t('research.saved')}
})
const importLegacy = () => mutate(async current => { await api.indexLegacySources(props.projectId); if (current()) { await refreshEvidence(); notice.value = t('research.saved') } })
const addNote = () => mutate(async current => { await api.saveReference(props.projectId,{subject_type:'project',subject_id:props.projectId,...noteDraft}); if (!current()) return; noteDraft.note = ''; await refreshEvidence(); notice.value = t('research.saved') })
async function refreshEvidence() { const token = generation; try { const [s,r] = await Promise.all([api.listSources(props.projectId,{limit:50,offset:0}),api.listReferences(props.projectId,{limit:50,offset:0})]); if (!valid(token)) return; sources.value = s.items; sourceTotal.value = s.total; references.value = r.items; referenceTotal.value = r.total; await loadQuality(token) } catch(err) { if (valid(token)) error.value = err.message } }
async function loadMore(kind) { if (pageBusy.value) return; const token = generation; pageBusy.value = true; try { const values = kind === 'sources' ? sources : references; const data = await (kind === 'sources' ? api.listSources : api.listReferences)(props.projectId,{offset:values.value.length,limit:50}); if (valid(token)) values.value.push(...data.items) } catch(err) { if (valid(token)) error.value = err.message } finally { if (alive) pageBusy.value = false } }
function inspectSource(source) { inspector.value = {sourceId:source.source_id} }
function inspectReference(reference) { inspector.value = {sourceId:reference.source_id,initialVersionId:reference.version_id,initialSpanId:reference.span_id,reference,subjectType:reference.subject_type,subjectId:reference.subject_id} }
const exportProject = format => mutate(async current => { const {blob,filename} = await api.downloadResearch(props.projectId,format); if (!current()) return; const url = URL.createObjectURL(blob), link = document.createElement('a'); link.href = url; link.download = filename; document.body.appendChild(link); link.click(); link.remove(); setTimeout(() => URL.revokeObjectURL(url),1000); notice.value = t('research.exportReady') })
watch(() => [props.projectId, mainSection.value], () => { stopTaskPolling(); generation++; detail.value = null; inspector.value = null; section.value = sections.includes(route.query.section) ? route.query.section : 'sources'; notice.value = ''; sourceDraft.title = sourceDraft.content = sourceDraft.identity = ''; noteDraft.note = ''; urlText.value = ''; plans.value = []; planDraft.scope = ''; refreshCurrent() })
onMounted(() => { document.addEventListener('visibilitychange',updateTaskPolling);loadProjects();refreshCurrent() })
onUnmounted(() => { alive = false;stopTaskPolling();document.removeEventListener('visibilitychange',updateTaskPolling);generation++;listGeneration++ })
</script>

