x; font-size:.875rem; }.checkbox input { width:18px; height:18px; }.new-research { border-top:1px solid var(--studio-line); padding-top:18px; }.content-tabs { display:flex; flex-wrap:wrap; gap:6px; border-bottom:1px solid var(--studio-line); margin:24px 0; padding-bottom:12px; }.content-tabs button { border-color:transparent; background:transparent; }.content-tabs button[aria-current=page] { background:var(--studio-button); color:var(--theme-on-filled); }.content-tabs button[aria-current=page] small { color:inherit; }.record { padding:20px 0; border-bottom:1px solid var(--studio-line); }.record:last-of-type { margin-bottom:20px; }.tag { display:inline-block; padding:3px 9px; border-radius:5px; background:var(--studio-paper); color:var(--studio-muted); font-size:.75rem; }.record p { margin:12px 0; }.record .heading-row { align-items:center; }.button-row { display:flex; gap:10px; flex-wrap:wrap; }.button-row button { flex-shrink:0; }.inline-form { display:flex; align-items:center; gap:10px; margin:16px 0; }.inline-form label { flex-shrink:0; margin:0; }.inline-form input { flex:1; min-width:0; }input,textarea,select { display:block; width:100%; border:1px solid var(--theme-control-line); border-radius:8px; padding:10px 12px; background:var(--studio-paper); color:var(--studio-ink); font:inherit; }label { display:block; font-weight:600; margin:14px 0 6px; }textarea { resize:vertical; }button,.button { display:inline-flex; justify-content:center; align-items:center; min-height:44px; padding:8px 14px; border:1px solid var(--theme-control-line); border-radius:8px; background:var(--studio-paper); color:var(--studio-ink); font:inherit; font-size:.875rem; text-decoration:none; cursor:pointer; }button:disabled { opacity:.55; cursor:default; }.primary { background:var(--studio-button); color:var(--theme-on-filled); }form > button { margin-top:16px; }.search-row > button { margin-top:0; white-space:nowrap; flex-shrink:0; min-width:64px; }.inline-form > button { margin:0; }a { color:var(--studio-ink); }.error { padding:12px; border-left:3px solid var(--studio-error); background:var(--theme-error-surface); color:var(--studio-error); overflow-wrap:anywhere; }.notice { padding:12px; background:var(--studio-soft); }.empty { padding:24px 0; color:var(--studio-muted); }details { margin:20px 0; }summary { cursor:pointer; font-weight:600; min-height:44px; padding:8px 0; }pre { white-space:pre-wrap; overflow-wrap:anywhere; background:var(--studio-paper); padding:16px; border-radius:8px; font-size:.8rem; }.quality-grid { display:grid; grid-template-columns:1fr 1fr; gap:24px; }.metric { font-size:1.8rem; font-variant-numeric:tabular-nums; }.welcome { padding:64px 16px; max-width:640px; }.welcome .button { margin-top:20px; }.eyebrow { color:var(--studio-accent); letter-spacing:3px; }.break { overflow-wrap:anywhere; }.plan-models {margin:20px 0;padding:12px;border:1px solid var(--studio-line);border-radius:8px;}.sr-only { position:absolute; width:1px; height:1px; overflow:hidden; clip:rect(0,0,0,0); }
